import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.annotation.*;
import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.util.*;

public class TestJacksonSafe {
  public static class SafeObjectMapper extends ObjectMapper {
    protected JsonParser wrap(JsonParser p) {
      if (p == null || p instanceof NoEmptyFieldNameParser) {
        return p;
      }
      return new NoEmptyFieldNameParser(p);
    }

    @Override
    protected Object _readMapAndClose(JsonParser p, JavaType valueType) throws java.io.IOException {
      return super._readMapAndClose(wrap(p), valueType);
    }

    @Override
    protected Object _readValue(DeserializationConfig cfg, JsonParser p, JavaType valueType) throws java.io.IOException {
      return super._readValue(cfg, wrap(p), valueType);
    }

    @Override
    protected JsonNode _readTreeAndClose(JsonParser p) throws java.io.IOException {
      return super._readTreeAndClose(wrap(p));
    }
  }

  public static class NoEmptyFieldNameParser extends JsonParserDelegate {
    public NoEmptyFieldNameParser(JsonParser d) { super(d); }

    @Override
    public JsonToken nextToken() throws java.io.IOException {
      JsonToken token = super.nextToken();
      if (token == JsonToken.FIELD_NAME) {
        String name = getCurrentName();
        if (name != null && name.isEmpty()) {
          throw new JsonParseException(this, "Empty JSON field name is not allowed");
        }
      }
      return token;
    }

    @Override
    public String nextFieldName() throws java.io.IOException {
      String name = super.nextFieldName();
      if (name != null && name.isEmpty()) {
        throw new JsonParseException(this, "Empty JSON field name is not allowed");
      }
      return name;
    }

    @Override
    public boolean nextFieldName(SerializableString str) throws java.io.IOException {
      boolean matched = super.nextFieldName(str);
      String name = getCurrentName();
      if (name != null && name.isEmpty()) {
        throw new JsonParseException(this, "Empty JSON field name is not allowed");
      }
      return matched;
    }
  }

  public static class Config { public boolean enabled; public Config(boolean enabled){this.enabled=enabled;} }
  public static class Bean { public final Config config; @JsonCreator public Bean(@JacksonInject Config config){this.config=config;} }

  public static void main(String[] args) throws Exception {
    SafeObjectMapper mapper = new SafeObjectMapper();
    mapper.configure(DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES, false);
    mapper.setInjectableValues(new InjectableValues.Std().addValue(Config.class, new Config(false)));
    try {
      Bean b = mapper.readValue("{\"\": {\"enabled\": true}}", Bean.class);
      System.out.println("enabled=" + b.config.enabled);
    } catch (JsonParseException e) {
      System.out.println("blocked:" + e.getMessage());
    }
  }
}
